<template>
  <div class="sites">
    <header class="page-header"><div><p class="eyebrow">SITES</p><h1>站点管理</h1><p>配置域名、回源地址和防护模式。</p></div><button class="primary" @click="openCreate">新增站点</button></header>
    <section class="mode-note"><span><b>MONITOR</b> 仅记录</span><span><b>PROTECT</b> 执行防护</span><span><b>EMERGENCY</b> 优先维护</span></section>
    <section class="card"><div class="card-head"><div><h2>接入站点</h2><p>{{ sites.length ? `已接入 ${sites.length} 个站点，按 Host 匹配。` : '建议先使用观察模式验证规则命中。' }}</p></div><button class="secondary" :disabled="loading" @click="loadSites">{{ loading ? '刷新中…' : '刷新' }}</button></div>
      <div v-if="sites.length" class="table-wrap"><table><thead><tr><th>域名</th><th>回源地址</th><th>模式</th><th>状态</th><th>更新时间</th><th></th></tr></thead><tbody><tr v-for="site in sites" :key="site.id"><td><strong>{{ site.domain }}</strong></td><td class="mono">{{ site.backend_url }}</td><td><span class="mode" :class="site.mode">{{ modeText(site.mode) }}</span></td><td><span class="status" :class="site.enabled ? 'enabled' : 'disabled'">{{ site.enabled ? '已启用' : '已停用' }}</span></td><td class="updated">{{ time(site.updated_at) }}</td><td class="actions"><button @click="openEdit(site)">编辑</button><button @click="toggle(site)">{{ site.enabled ? '停用' : '启用' }}</button><button class="danger" @click="remove(site)">删除</button></td></tr></tbody></table></div>
      <div v-else class="empty"><h3>还没有接入站点</h3><p>添加域名后，WAF 会按配置的模式进行路由和防护。</p><button class="primary" @click="openCreate">添加站点</button></div>
    </section>
    <div v-if="dialog" class="overlay" @click.self="dialog=false"><form class="dialog" @submit.prevent="save"><div class="dialog-head"><div><h2>{{ editing ? '编辑站点' : '新增站点' }}</h2><p>请使用完整的 HTTP 或 HTTPS 回源地址。</p></div><button type="button" aria-label="关闭" @click="dialog=false">×</button></div>
      <div class="fields"><label>域名<input v-model.trim="form.domain" placeholder="api.example.com" autocomplete="off" required><small>支持精确域名和 <code>*.example.com</code> 泛域名。</small></label><label>回源地址<input v-model.trim="form.backend_url" placeholder="http://127.0.0.1:3000" autocomplete="off" required><small>建议使用内网地址，避免回源循环。</small></label></div>
      <label>防护模式<select v-model="form.mode"><option value="monitor">MONITOR · 仅记录风险</option><option value="protect">PROTECT · 执行风险动作</option><option value="emergency">EMERGENCY · 进入维护</option></select></label><label class="toggle"><input type="checkbox" v-model="form.enabled"><span>立即启用站点</span></label><p v-if="form.mode==='emergency'" class="warning">紧急模式会优先返回维护页，仅建议用于应急处置。</p><div class="dialog-actions"><button type="button" class="secondary" @click="dialog=false">取消</button><button class="primary" :disabled="saving">{{ saving ? '保存中…' : '保存' }}</button></div>
    </form></div>
  </div>
</template>
<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import api from '../api'
const sites = ref([]), dialog = ref(false), editing = ref(false), saving = ref(false), loading = ref(false)
const form = reactive(blank())
function blank() { return { id: null, domain: '', backend_url: '', mode: 'protect', enabled: true } }
function unwrap(r) { return r?.data ?? r ?? [] }
async function loadSites() { loading.value = true; try { sites.value = unwrap(await api.get('/sites')) } catch {} finally { loading.value = false } }
function openCreate() { Object.assign(form, blank()); editing.value = false; dialog.value = true }
function openEdit(site) { Object.assign(form, JSON.parse(JSON.stringify(site))); editing.value = true; dialog.value = true }
async function save() { saving.value = true; try { if (editing.value) await api.put(`/sites/${form.id}`, form); else await api.post('/sites', form); ElMessage.success('站点配置已保存'); dialog.value = false; await loadSites() } finally { saving.value = false } }
async function toggle(site) { await api.put(`/sites/${site.id}`, { ...site, enabled: !site.enabled }); ElMessage.success(site.enabled ? '站点已停用' : '站点已启用'); await loadSites() }
async function remove(site) { try { await ElMessageBox.confirm(`确认删除站点「${site.domain}」？`, '删除站点', { type: 'warning', confirmButtonText: '删除', cancelButtonText: '取消' }); await api.delete(`/sites/${site.id}`); ElMessage.success('站点已删除'); await loadSites() } catch {} }
function modeText(mode) { return { monitor: '观察模式', protect: '防护模式', emergency: '紧急维护' }[mode] || mode }
function time(value) { return value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '-' }
onMounted(loadSites)
</script>
<style scoped>
.sites { display: flex; flex-direction: column; gap: 14px; color: #0f172a; }.page-header,.card,.mode-note { border: 1px solid #e2e8f0; border-radius: 10px; background: #fff; }.page-header { display: flex; justify-content: space-between; align-items: center; gap: 18px; padding: 22px 24px; }.eyebrow { margin: 0 0 4px; color: #64748b; font: 700 10px/1.4 ui-monospace,monospace; letter-spacing: .08em; }.page-header h1,.card h2,.dialog h2 { margin: 0; font-size: 18px; }.page-header p,.card-head p,.dialog-head p { margin: 5px 0 0; color: #64748b; font-size: 12px; }.primary,.secondary,.actions button { height: 34px; border-radius: 7px; padding: 0 11px; font: 700 12px inherit; cursor: pointer; }.primary { border: 1px solid #2563eb; background: #2563eb; color: #fff; }.primary:disabled { opacity: .6; cursor: not-allowed; }.secondary,.actions button { border: 1px solid #dbe3ee; background: #fff; color: #475569; }.secondary:hover,.actions button:hover { border-color: #bfdbfe; color: #1d4ed8; background: #f8fafc; }.mode-note { display: flex; gap: 22px; padding: 11px 15px; color: #64748b; font-size: 12px; }.mode-note b { margin-right: 5px; color: #334155; font: 700 10px ui-monospace,monospace; }.card { overflow: hidden; }.card-head { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 16px 18px; border-bottom: 1px solid #eef2f7; }.card-head h2 { font-size: 14px; }.table-wrap { overflow: auto; }table { width: 100%; min-width: 760px; border-collapse: collapse; }th,td { padding: 12px 16px; border-bottom: 1px solid #eef2f7; text-align: left; font-size: 12px; }th { background: #f8fafc; color: #64748b; font-size: 10px; font-weight: 700; }tbody tr:hover { background: #f8fafc; }.mono { color: #475569; font-family: ui-monospace,monospace; }.mode { display: inline-block; border-radius: 4px; padding: 3px 6px; background: #f1f5f9; color: #475569; font-size: 11px; }.mode.monitor { background: #eff6ff; color: #1d4ed8; }.mode.protect { background: #ecfdf5; color: #047857; }.mode.emergency { background: #fef2f2; color: #dc2626; }.status { font-size: 12px; font-weight: 700; }.status.enabled { color: #047857; }.status.disabled { color: #94a3b8; }.updated { color: #64748b; }.actions { display: flex; justify-content: flex-end; gap: 6px; }.actions button { height: 28px; font-size: 11px; }.actions .danger { color: #dc2626; border-color: #fecaca; }.empty { padding: 52px 20px; text-align: center; }.empty h3 { margin: 0; font-size: 15px; }.empty p { margin: 7px 0 16px; color: #64748b; font-size: 12px; }.overlay { position: fixed; z-index: 200; inset: 0; display: grid; place-items: center; padding: 18px; background: rgba(15,23,42,.32); }.dialog { width: min(580px,100%); padding: 20px; border: 1px solid #e2e8f0; border-radius: 10px; background: #fff; box-shadow: 0 16px 36px rgba(15,23,42,.14); }.dialog-head { display: flex; justify-content: space-between; gap: 18px; margin-bottom: 18px; }.dialog-head h2 { font-size: 16px; }.dialog-head button { width: 28px; height: 28px; border: 0; border-radius: 5px; background: #fff; color: #64748b; font-size: 22px; cursor: pointer; }.fields { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }.dialog label { display: flex; flex-direction: column; gap: 6px; margin: 13px 0; color: #334155; font-size: 12px; font-weight: 700; }.dialog input:not([type="checkbox"]),.dialog select { width: 100%; height: 36px; border: 1px solid #dbe3ee; border-radius: 7px; padding: 0 10px; background: #fff; color: #0f172a; font: inherit; outline: none; }.dialog input:focus,.dialog select:focus { border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37,99,235,.1); }.dialog small { color: #94a3b8; font-size: 11px; font-weight: 400; }.dialog code { color: #2563eb; }.toggle { flex-direction: row !important; align-items: center; gap: 8px !important; padding: 10px; border: 1px solid #e2e8f0; border-radius: 7px; background: #f8fafc; cursor: pointer; }.toggle input { accent-color: #2563eb; }.warning { padding: 9px 10px; border: 1px solid #fde68a; border-radius: 7px; background: #fffbeb; color: #92400e; font-size: 12px; }.dialog-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 18px; }@media(max-width:720px) { .page-header { align-items: flex-start; flex-direction: column; }.mode-note { flex-direction: column; gap: 7px; }.fields { grid-template-columns: 1fr; } }@media(max-width:560px) { .page-header { padding: 18px; }.page-header .primary { width: 100%; }.dialog { padding: 18px; }.dialog-actions>* { flex: 1; } }
</style>
